async function prepareVoiceWaveform(path: string, signal?: AbortSignal) {
  const ffmpeg = ["/opt/homebrew/bin/ffmpeg", "/usr/local/bin/ffmpeg"].find(existsSync);
  if (!ffmpeg || signal?.aborted) return "";
  const sampleRate = 8000;
  const maxSeconds = 120;
  try {
    const { stdout } = await runMediaConverter(ffmpeg, ["-nostdin", "-v", "error", "-protocol_whitelist", "file",
      "-f", "ogg", "-i", path, "-map", "0:a:0", "-t", String(maxSeconds + 1), "-ac", "1", "-ar", String(sampleRate),
      "-c:a", "pcm_s16le", "-f", "s16le", "pipe:1"],
    { encoding: "buffer", timeout: 15_000, maxBuffer: (maxSeconds + 1) * sampleRate * 2, signal });
    return stdout.length <= maxSeconds * sampleRate * 2 ? encodeVoiceWaveform(stdout) : "";
  } catch { return ""; }
}
const timeFormat = new Intl.DateTimeFormat(undefined, { dateStyle: "short", timeStyle: "short" });

function syncedTextDraft(container: TdObject): SyncedDraft | undefined {
  const draft = object(container.draft_message);
  if (draft?.["@type"] !== "draftMessage" || draft.reply_to || draft.reply_to_message_id || draft.suggested_post_info
    || (draft.effect_id !== undefined && draft.effect_id !== "0" && draft.effect_id !== 0)) return;
  const content = object(draft.content) ?? object(draft.input_message_text);
  if (content?.["@type"] !== "draftMessageContentText" && content?.["@type"] !== "inputMessageText") return;
  const options = object(content.link_preview_options);
  if (options?.force_small_media || options?.force_large_media) return;
  const parts = formattedMessageParts(object(content.text));
  const text = parts.text;
  if (typeof text !== "string" || !text.trim() || text.length > 4096) return;
  const styles = [...parts.styles, ...parts.spoilers];
  const links = parts.links.filter((link) => link.hidden).map(({ offset, length, url }) => ({ offset, length, url }));
  const { customEmoji } = parts;
  const explicit = parts.entities.filter((entry) => object(object(entry)?.type)?.["@type"] !== "textEntityTypeUrl");
  if (explicit.some((entry) => {
    const type = object(object(entry)?.type)?.["@type"];
    return type !== "textEntityTypeTextUrl" && type !== "textEntityTypeCustomEmoji" && !Object.values(outgoingTextStyles).includes(type ?? "");
  }) || explicit.length !== styles.length + links.length + customEmoji.length || !validDraftStyles(text, styles)
    || !validDraftLinks(text, links, styles) || !validDraftCustomEmoji(text, customEmoji, styles, links)) return;
  const url = typeof options?.url === "string" && options.url ? webLink(options.url)?.href : undefined;
  if (options?.url && (!url || !textWebLinks(text).some((link) => link.href === url))) return;
  const disabled = options?.is_disabled === true || (!options && content.disable_web_page_preview === true);
  const preview: DraftPreview | undefined = disabled ? { mode: "disabled" }
    : url || options?.show_above_text === true
      ? { mode: "enabled", ...(url ? { url } : {}), ...(options?.show_above_text === true ? { above: true } : {}) }
      : undefined;
  return { text, ...(styles.length ? { styles } : {}), ...(links.length ? { links } : {}),
    ...(customEmoji.length ? { customEmoji } : {}), ...(preview ? { preview } : {}) };
}

function userPresence(value: unknown): UserPresence {
  const status = object(value);
  const unix = (value: unknown): value is number => typeof value === "number" && Number.isInteger(value)
    && value > 0 && value <= 2147483647;
  switch (status?.["@type"]) {
    case "userStatusOnline": if (unix(status.expires)) return { state: "online", expires: status.expires }; break;
    case "userStatusOffline": if (unix(status.was_online)) return { state: "offline", lastSeen: status.was_online }; break;
    case "userStatusRecently": return { state: "recently" };
    case "userStatusLastWeek": return { state: "week" };
    case "userStatusLastMonth": return { state: "month" };
  }
  return { state: "unavailable" };
}

function messageTime(date: unknown): string {
  return typeof date === "number" && date > 0 && date <= 8.64e12 ? timeFormat.format(date * 1000) : "";
}

function object(value: unknown): TdObject | undefined {
  return value && typeof value === "object" && "@type" in value ? value as TdObject : undefined;
}

function messageRestriction(raw: TdObject): string | undefined {
  const reason = object(raw.restriction_info)?.restriction_reason;
  if (typeof reason === "string" && reason.trim()) return reason.trim().slice(0, 512);
}

function readDownloadCounts(value: unknown): DownloadQueueCounts | undefined {
  const row = object(value);
  if (row?.["@type"] !== "downloadedFileCounts") return;
  return downloadQueueCounts.safeParse({
    active: row.active_count, paused: row.paused_count, completed: row.completed_count,
  }).data;
}

function readStarAmount(value: unknown) {
  const amount = object(value);
  const stars = amount?.star_count;
  const nanostars = amount?.nanostar_count;
  return amount?.["@type"] === "starAmount" && typeof stars === "number" && Number.isSafeInteger(stars)
    && typeof nanostars === "number" && Number.isInteger(nanostars) && Math.abs(nanostars) < 1000000000
    && (stars === 0 || nanostars === 0 || Math.sign(stars) === Math.sign(nanostars)) ? { stars, nanostars } : undefined;
}

function readStarRevenueGraph(graph: TdObject | undefined) {
  if (graph?.["@type"] !== "statisticalGraphData" || typeof graph.json_data !== "string" || graph.json_data.length > 1_048_576) return;
  let data: { columns?: unknown; types?: Record<string, unknown>; names?: Record<string, unknown> };
  try { data = JSON.parse(graph.json_data); }
  catch { return; }
  if (!data || !Array.isArray(data.columns) || data.columns.length < 2 || data.columns.length > 50 || !data.types) return;
  const columns = data.columns.filter((column): column is unknown[] => Array.isArray(column)
    && typeof column[0] === "string" && column.length >= 2 && column.length <= 3661);
  const axis = columns.find(([id]) => data.types?.[String(id)] === "x");
  if (!axis) return;
  const dates = axis.slice(1);
  if (!dates.every((date, index): date is number => typeof date === "number" && Number.isSafeInteger(date)
    && date > 0 && date <= 8640000000000000 && (index === 0 || date > Number(dates[index - 1])))) return;
  const series = columns.flatMap(([id, ...values]) => {
    const kind = data.types?.[String(id)];
    if (kind !== "bar" && kind !== "line" && kind !== "area" && kind !== "step") return [];
    if (values.length !== dates.length || !values.every((number): number is number => typeof number === "number" && Number.isFinite(number))) return [];
    const label = data.names?.[String(id)];
    const name = typeof label === "string" ? label.trim().slice(0, 128) || "Daily revenue" : "Daily revenue";
    return [{ name, points: dates.map((date, index) => ({ date, stars: values[index]! })) }];
  });
  return series.length ? series : undefined;
}

