        const result = await request(color === null ? { "@type": "deleteChatBackground", chat_id, restore_previous: false }
          : { "@type": "setChatBackground", chat_id, background: null, only_for_self: true, dark_theme_dimming: 76,
            type: { "@type": "backgroundTypeFill", fill: { "@type": "backgroundFillSolid", color: Number.parseInt(color.slice(1), 16) } } });
