      const change = parsed.data;
      const profile = await profileGiftOwner(id);
      const owner_id = profile.owner;
      if (!await canManageProfileGifts(profile)) return { state: "unavailable" as const };
      if (change.action === "move") {
        const collections = await readGiftCollections(owner_id);
        const ids = collections.map(({ id }) => id);
        if (ids.length !== change.expectedOrder.length || ids.some((id, index) => id !== change.expectedOrder[index])) {
          return { state: "changed" as const };
        }
        const from = ids.indexOf(change.collection);
        const to = from + (change.direction === "up" ? -1 : 1);
        if (from < 0 || to < 0 || to >= ids.length) return { state: "unavailable" as const };
        const reordered = [...collections];
        [reordered[from], reordered[to]] = [reordered[to]!, reordered[from]!];
        requireReady();
        const result = await request({ "@type": "reorderGiftCollections", owner_id, collection_ids: reordered.map(({ id }) => id) });
        return result["@type"] === "ok" ? { state: "applied" as const, collections: reordered } : { state: "unavailable" as const };
      }
      if (change.action !== "create") {
        const collections = await readGiftCollections(owner_id);
        if (collections.find(({ id }) => id === change.collection)?.name !== change.expectedName) return { state: "changed" as const };
        if (change.action === "delete") {
          requireReady();
          const result = await request({ "@type": "deleteGiftCollection", owner_id, collection_id: change.collection });
          return result["@type"] === "ok"
            ? { state: "applied" as const, collections: collections.filter(({ id }) => id !== change.collection) }
            : { state: "unavailable" as const };
        }
      }
      requireReady();
      const raw = await request(change.action === "create" ? {
        "@type": "createGiftCollection", owner_id, name: change.name, received_gift_ids: [],
      } : { "@type": "setGiftCollectionName", owner_id, collection_id: change.collection, name: change.name });
      const collection = giftCollectionView(raw);
      if (!collection || (change.action === "rename" && collection.id !== change.collection)) {
        return { state: "unavailable" as const };
      }
      return { state: "saved" as const, collection };
