        const emoji = typeof sticker?.emoji === "string" ? sticker.emoji.slice(0, 24) : undefined;
        const title = upgraded && typeof gift.title === "string" ? gift.title.trim().slice(0, 256) : "";
        const slug = upgraded && typeof gift.name === "string" && /^[a-zA-Z0-9-]{1,128}$/.test(gift.name) ? gift.name : undefined;
