      const digits = typeof user.phone_number === "string" ? user.phone_number.replace(/^\+/, "") : "";
      const formatted = typeof full.bio === "string" ? { "@type": "formattedText", text: full.bio } : object(full.bio);
      const { text, links, styles, spoilers, maxStyles } = formattedMessageParts(formatted);
      const birthdate = telegramBirthdate.safeParse(full.birthdate);
      const type = object(user.type);
      const emojiStatus = readProfileEmojiStatus(user.emoji_status);
      const isBot = type?.["@type"] === "userTypeBot";
      const note = user.is_contact === true && !isBot ? contactNoteContent(formattedMessageParts(object(full.note))) : undefined;
      const botCanManageEmojiStatus = isBot && object(full.bot_info)?.can_manage_emoji_status === true;
