      const [account, user] = await Promise.all([archiveAccount(), request({ "@type": "getUser", user_id: peer.user_id })]);
      if (state.state !== "ready" || user["@type"] !== "user" || user.id !== peer.user_id || object(user.type)?.["@type"] !== "userTypeBot") return false;
