      const anchor = cursor === undefined ? await historyDateAnchor(chat_id, range, signal) : undefined;
      if (anchor === null) return { messages: [], before: null };
      const from_message_id = cursor ?? Number(anchor?.id ?? 0);
      const result = await request({ "@type": "searchChatMessages", chat_id, query, from_message_id, offset: 0, limit: 25,
        ...(topicId !== undefined && { topic_id: { "@type": "messageTopicForum", forum_topic_id: topicId } }),
      }, undefined, signal);
