      const { readInbox, unread } = inboxReadState(topic);
      const latest = object(topic.last_message);
      const latestId = inboxMessage(latest, directId, topic_id) ? latest.id : undefined;
      const openUnread = before === undefined && after === undefined && unread > 0 && readInbox !== undefined;
      const startsAtBeginning = openUnread && readInbox === 0;
