      const available = items.filter((item) => !item.sending_state && !item.scheduling_state).reverse();
      const openAt = openUnread
        ? available.find(({ id }) => id === anchor && !startsAtBeginning)
          ?? available.find(({ id, is_outgoing }) => id > (readInbox ?? 0) && is_outgoing === false)
          ?? available.find(({ id }) => id > (readInbox ?? 0)) : undefined;
      const newest = items[0]?.id;
