      if (!source.linked) return { editable: source.editable, current: null };
      const linked = await request({ "@type": "getChat", chat_id: source.linked }).catch(() => undefined);
      const type = object(linked?.type);
      const verified = linked?.["@type"] === "chat" && linked.id === source.linked && type?.["@type"] === "chatTypeSupergroup"
        && (type.is_channel === true) !== source.channel;
