      const candidates = await Promise.all(ids.filter((candidate) => candidate !== source.chat_id && candidate !== source.linked)
        .slice(0, 100).map((candidate) => discussionGroupCandidate(candidate).catch(() => undefined)));
      return candidates.flatMap((candidate) => candidate ? [candidate.view] : []);
