      const savedSounds = sound !== undefined || stories?.sound !== undefined ? await savedNotificationSounds().catch(() => []) : undefined;
      return { ...values, ...(sound === undefined ? {} : { sound }), ...(stories ? { stories } : {}),
        ...(savedSounds ? { savedSounds } : {}) };
