      const { emoji, type } = effect;
      const reaction = type?.["@type"] === "messageEffectTypeEmojiReaction";
      const sticker = object(reaction ? type.effect_animation
        : type?.["@type"] === "messageEffectTypePremiumSticker" ? type.sticker : undefined);
      const premium = object(object(sticker?.full_type)?.premium_animation);
      const file = !reaction && premium ? premium
        : object(sticker?.format)?.["@type"] === "stickerFormatTgs" ? object(sticker?.sticker) : undefined;
