      requireReady();
      const result = await request({ "@type": "setBusinessOpeningHours", opening_hours: hours ? {
        "@type": "businessOpeningHours", time_zone_id: hours.zone, opening_hours: hours.intervals.map(({ startMinute, endMinute }) => ({
          "@type": "businessOpeningHoursInterval", start_minute: startMinute, end_minute: endMinute,
        })),
      } : null });
