      if (!Number.isSafeInteger(chat_id) || !chat_id || !Number.isSafeInteger(message_id) || message_id <= 0) {
        throw new Error("Invalid photo reference.");
      }
      const raw = await request({ "@type": "getMessage", chat_id, message_id });
      await prepareSensitiveMessages([raw]);
      if (blockedMessage(raw)) throw new Error("No eligible photo.");
      const content = object(raw.content);
      const matches = raw.chat_id === chat_id && raw.id === message_id;
      if (attachment?.paid) {
        const item = matches ? paidAttachment(raw, attachment.index) : undefined;
        const variants = paidPhotoVariants(item);
        if (!variants || variants.large !== attachment.fileId) throw new Error("No eligible photo.");
        const photo = await downloadTelegramPhoto(variants[size]);
        return size === "preview" && variants.preview !== variants.large ? { ...photo, hasLarger: true } : photo;
      }
      if (attachment) {
        if (!matches || raw["@type"] !== "message" || content?.["@type"] !== "messageRichMessage"
          || raw.sending_state || raw.self_destruct_type || raw.ttl || content.is_secret) throw new Error("No eligible photo.");
        const block = richBlockAt(content.message, attachment);
        const variants = block?.["@type"] === "pageBlockPhoto" ? jpegPhotoVariants(object(block.photo)?.sizes) : undefined;
        if (!variants || variants.large !== attachment.fileId) throw new Error("No eligible photo.");
        const photo = await downloadTelegramPhoto(variants[size]);
        return size === "preview" && variants.preview !== variants.large ? { ...photo, hasLarger: true } : photo;
      }
      const files = matches ? photoFiles(raw) : undefined;
      let file_id = files?.[size];
      if (file_id === undefined && raw.chat_id === chat_id && raw.id === message_id
        && content?.["@type"] === "messageSticker" && mayShareHistoryMessage(raw) && await canExportChatContent(chat_id)) {
        file_id = stickerPhotoId(object(content.sticker), size === "large");
      }
      if (file_id === undefined) throw new Error("No eligible photo.");
