      if (searchRequiresEmptyQuery(filter) && (query || sender || range)) throw new Error("This unread activity filter only supports a chat or topic.");
      if (range && !messageSearchDateRange.safeParse(range).success) throw new Error("Invalid search dates.");
      const media = filter === undefined ? undefined : messageSearchFilters[filter];
